async function refreshCsrfToken(){const response=await fetch('/portal/state',{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok||typeof data.csrf!=='string'||!data.csrf)throw new Error(data.message||'Your session could not be refreshed. Please reload and try again.');window.PORTAL_CONFIG.csrf=data.csrf;}
async function api(path,method='GET',body,extraHeaders={}){if(!native)throw new Error('Sign-in is temporarily unavailable. Please check back soon.');const multipart=body instanceof FormData;const request=()=>fetch('/portal/'+path,{method,credentials:'same-origin',headers:{'Accept':'application/json',...(multipart?{}:{'Content-Type':'application/json'}),'X-CSRF-TOKEN':window.PORTAL_CONFIG?.csrf||'',...extraHeaders},...(body?{body:multipart?body:JSON.stringify(body)}:{})});let r=await request();if(r.status===419&&method!=='GET'){await refreshCsrfToken();r=await request();}const data=await r.json().catch(()=>({message:'Unable to reach the portal. Please try again.'}));if(data.csrf)window.PORTAL_CONFIG.csrf=data.csrf;if(!r.ok){if(r.status===401&&state.user){state.user=null;clearAdminCache();closeModal();go('login');toast('Your session ended. Please sign in again.');}throw new Error(r.status===419?'Your session expired or could not be verified. Please refresh the page and try again.':Object.values(data.errors||{}).flat()[0]||data.message||'Please try again.');}return data;}
